import json
from datetime import datetime
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import build_window, utc_pair, wall_clock_pair


def _parse_iso(value):
    """Parse ISO 8601 values, including the standard UTC ``Z`` suffix."""
    return datetime.fromisoformat(value[:-1] + "+00:00" if value.endswith("Z") else value)


def validate_range(payload):
    """Return all local validation errors for one query.

    The API accepts an omitted end bound, but a supplied end bound is a
    range endpoint and is compared only after both values have been put on
    the UTC timeline.  ``parse_bound`` (via ``build_window``) applies the
    project's explicit UTC policy to timestamps without an offset.
    """
    errors = []

    if not isinstance(payload, dict):
        return [build_rejection("query", "must be an object", payload)]
    if "start_date" not in payload:
        errors.append(build_rejection("start_date", "is required", payload))
    elif not isinstance(payload["start_date"], str):
        errors.append(build_rejection("start_date", "must be an ISO 8601 string", payload))
    else:
        try:
            _parse_iso(payload["start_date"])
        except ValueError as exc:
            errors.append(build_rejection("start_date", f"invalid ISO 8601 timestamp: {exc}", payload))

    if "end_date" in payload and not isinstance(payload["end_date"], str):
        errors.append(build_rejection("end_date", "must be an ISO 8601 string", payload))
    elif "end_date" in payload:
        try:
            _parse_iso(payload["end_date"])
        except ValueError as exc:
            errors.append(build_rejection("end_date", f"invalid ISO 8601 timestamp: {exc}", payload))

    if errors:
        # Do not try to compare a partially valid window, but retain all basic
        # field errors so one bad query gets one complete diagnostic report.
        return errors

    window = build_window(payload)

    if "end_date" not in payload:
        return []

    start_utc, end_utc = utc_pair(window)
    start_local, end_local = wall_clock_pair(window)
    normalized = {
        "start_utc": start_utc.isoformat(),
        "end_utc": end_utc.isoformat(),
        "naive_timezone_policy": MISSING_TZ_POLICY,
        "default_timezone": str(DEFAULT_TIMEZONE),
    }

    if end_utc < start_utc:
        errors.append(
            build_rejection(
                "date_range",
                "end must be greater than or equal to start after UTC normalization",
                payload,
                normalized=normalized,
            )
        )

    # A fall-back overlap is treated as ambiguous local input by the service.
    # It is distinct from ordinary UTC ordering because the later occurrence
    # can have a later UTC instant despite an earlier wall-clock endpoint.
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start_local > end_local
        and window["start"].utcoffset() != window["end"].utcoffset()
    ):
        errors.append(
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range: end wall-clock time is earlier than start",
                payload,
                normalized=normalized,
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

