from __future__ import annotations

from datetime import datetime, timezone

from timezone_defaults import DEFAULT_TIMEZONE


def parse_bound(value):
    # Python 3.10's fromisoformat does not recognize the ISO 8601 ``Z``
    # designator, although it is equivalent to an explicit UTC offset.
    parsed = datetime.fromisoformat(value[:-1] + "+00:00" if value.endswith("Z") else value)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=DEFAULT_TIMEZONE)
    return parsed


def build_window(payload):
    window = {
        "start": parse_bound(payload["start_date"]),
        "payload": payload,
    }
    if "end_date" in payload:
        window["end"] = parse_bound(payload["end_date"])
    return window


def wall_clock_pair(window):
    return (
        window["start"].replace(tzinfo=None),
        window["end"].replace(tzinfo=None),
    )


def calendar_day_pair(window):
    return (
        window["start"].date(),
        window["end"].date(),
    )


def utc_pair(window):
    return (
        window["start"].astimezone(timezone.utc),
        window["end"].astimezone(timezone.utc),
    )
